using UnityEngine;using UnityEditor;using System.Linq;using System.IO;
namespace Jimothy.Editor{public static class InspectCharacter{public static void Run(){var go=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Jimothy/Resources/Jimothy.fbx");File.WriteAllText("../character-import.txt",string.Join("\n",go.GetComponentsInChildren<SkinnedMeshRenderer>().Select(r=>r.name+" colors="+r.sharedMesh.colors.Length+" first="+string.Join(";",r.sharedMesh.colors.Take(3).Select(c=>c.ToString()))+" mat="+string.Join(";",r.sharedMaterials.Select(m=>m.name+":"+(m.mainTexture?m.mainTexture.name:"none"))))));}}}
